pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 lockTime1, uint256 lockTime2, uint256 amount) public {
        // Admissible domain: reduce values to feasible reasonable bounds
        lockTime1 = bound(lockTime1, 1, 365 days);
        lockTime2 = bound(lockTime2, 1, 365 days);
        amount = bound(amount, 1, 1000 ether);

        // Use a deterministic actor (address always exists as EOA, fuzz provided no actor)
        address actor = address(0x100);

        // Fund actor and do first deposit
        vm.deal(actor, amount * 2);
        vm.prank(actor);
        c.Put{value: amount}(lockTime1);
        uint256 firstUnlock = block.timestamp + lockTime1;

        // Warp slightly forward so second deposit happens at a different timestamp
        vm.warp(block.timestamp + 1);

        // Second deposit with lockTime2 (fund actor again to be safe)
        vm.deal(actor, amount);
        vm.prank(actor);
        c.Put{value: amount}(lockTime2);
        uint256 secondUnlock = block.timestamp + lockTime2;

        // After both calls, the unlockTime must equal the maximum of the two deposit timestamps
        // This holds for the original contract; the mutant breaks it when secondUnlock < firstUnlock
        uint256 finalUnlock = c.Acc(actor).unlockTime;
        assertTrue(finalUnlock == (firstUnlock > secondUnlock ? firstUnlock : secondUnlock));
    }
}

