pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
        c.SetMinSum(0);
        c.SetLogFile(address(new Log()));
        c.Initialized();
    }

    function testFuzz_property(uint256 lockTime1, uint256 lockTime2) public {
        // Keep lockTimes admissible and ensure they satisfy lockTime1 > lockTime2
        vm.assume(lockTime1 > lockTime2);
        vm.assume(lockTime1 <= type(uint128).max);
        vm.assume(lockTime2 <= type(uint128).max);

        address user = address(0x1234);
        uint256 amount1 = 1 ether;
        uint256 amount2 = 1 ether;

        vm.deal(user, amount1 + amount2);

        // Put with a longer lockTime
        vm.prank(user);
        c.Put{value: amount1}(lockTime1);

        // Warp forward but ensure unlockTime still valid
        vm.warp(block.timestamp + 1);

        // Put with a strictly smaller lockTime
        vm.prank(user);
        c.Put{value: amount2}(lockTime2);

        // After the second Put, the unlockTime in the reference MUST be block.timestamp+lockTime1 (the larger)
        // The mutant overwrites it with block.timestamp+lockTime2 (the smaller).
        // We warp just past the mutant's smaller unlockTime but before the reference's larger unlockTime.
        uint256 mutantUnlock = block.timestamp + lockTime2; // current timestamp is after second Put
        uint256 refUnlock = (block.timestamp - 1) + lockTime1; // first Put's unlockTime (since we warped 1s)
        // We need warp exactly to a time where mutant can Collect but reference cannot:
        // warp to mutantUnlock + 1
        vm.warp(mutantUnlock + 1);
        // At this point, block.timestamp > mutant unlockTime but still <= ref unlockTime if refUnlock > mutantUnlock
        // Since lockTime1 > lockTime2, refUnlock is strictly greater than mutantUnlock, so the reference should not allow Collect, but the mutant should.

        // Try Collect; it should fail (revert) in the reference but succeed in the mutant.
        // So we assert that the call reverts.
        (bool ok, ) = address(c).call(abi.encodeWithSignature("Collect(uint256)", 1));
        assertTrue(!ok, "Reference should not allow Collect before original unlockTime");
    }
}

