pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 firstLock, uint256 secondLock, uint256 collectAmt) public {
        // Assume second lock time is strictly less than first so the mutant forcibly shortens unlockTime
        vm.assume(secondLock < firstLock);
        // Bound lock times to avoid overflow and keep within reasonable limits
        firstLock = bound(firstLock, 1, 10_000);
        secondLock = bound(secondLock, 1, firstLock - 1);
        // Bound collect amount to be non-zero and not exceed deposit
        collectAmt = bound(collectAmt, 1, 10 ether);

        // Deploy a failing callee that will cause LogFile.AddMessage to revert
        FailingCallee failing = new FailingCallee();

        // Initialize the contract and set the failing address as LogFile
        c.SetMinSum(1);
        c.SetLogFile(address(failing));
        c.Initialized();

        // Fund a test actor
        address actor = makeAddr("actor");
        uint256 depositAmount = collectAmt * 2;
        vm.deal(actor, depositAmount * 2);

        // First Put: call Put with firstLock
        vm.prank(actor);
        c.Put{value: depositAmount}(firstLock);

        // Warp to a time AFTER the first lock time would have expired,
        // but the unlockTime stored by reference may still be in the future due to the second Put
        uint256 warpTime = block.timestamp + firstLock + 1;
        vm.warp(warpTime);

        // Second Put: call Put with secondLock (smaller lock time)
        vm.prank(actor);
        c.Put{value: depositAmount}(secondLock);

        // Record whether collection succeeds. Because LogFile is the failing callee,
        // the Collect call's internal log call will revert if executed.
        // In the reference: unlockTime = max(first expiry, second expiry) = first expiry (which is in the past),
        // so Collect will execute the balance transfer and then call LogFile.AddMessage, which reverts the whole tx.
        // In the mutant: unlockTime = second expiry (which is in the future because secondLock < firstLock and we warped to exactly firstLock+1),
        // so Collect will be blocked by block.timestamp > acc.unlockTime check, and the tx will succeed but do nothing.
        // Actually, we need a succeeding outcome for collect in one and revert in the other.
        // Wait: if reference UnlockTime = max(now+first, now+second) = now+first (in the past after warp),
        // it will attempt the call and revert due to LogFile. In mutant, unlockTime = now+second (in the future after warp),
        // so Collect() will not enter the if body and succeed without revert.

        // We must ensure MinSum and balance conditions are met (MinSum=1, balance=depositAmount*2 >= collectAmt)
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmt));

        // The property: the reference must revert on this Collect (due to LogFile revert), the mutant must succeed.
        // Since we are testing the contract, we assert that Collect always reverts on the reference
        // (the reference satisfies this because unlockTime is in the past and LogFile is failing).
        // The buggy version will succeed because unlockTime is in the future, so assertion of revert will fail for the mutant.
        assertFalse(ok, "Collect should revert on reference due to LogFile, but mutant succeeds");
    }
}

contract FailingCallee {
    fallback() external payable {
        revert("LogFile intentionally reverts");
    }
}

